        try:
            stdout, stderr = benchmark_proc.communicate(timeout=BENCHMARK_TIMEOUT_SECS)
        except subprocess.TimeoutExpired:
            benchmark_proc.kill()
            stdout, stderr = benchmark_proc.communicate()
            return _error_result(
                f"Correctness test timed out after {BENCHMARK_TIMEOUT_SECS} seconds",
                system_observation={
                    "before": observation_before,
                    "after": _collect_system_observation(cpu_cores=cpu_cores, focus_pids=(child.pid,)),
                    "server_pid": child.pid,
                    "benchmark_pid": benchmark_proc.pid,
                },
            )
        observation_after = _collect_system_observation(cpu_cores=cpu_cores, focus_pids=(child.pid,))
        if benchmark_proc.returncode != 0:
            return _error_result(
                f"Correctness test exited with code {benchmark_proc.returncode}: {(stderr or stdout)[:2000]}",
                system_observation={
                    "before": observation_before,
                    "after": observation_after,
                    "server_pid": child.pid,
                    "benchmark_pid": benchmark_proc.pid,
                },
            )
        output = json.loads(stdout)
        bench = output["benchmark"]
        passed = float(bench.get("recall", 0.0)) >= RECALL_THRESHOLD
        message = (
            f"Correctness test PASSED: recall {bench['recall']:.4f} >= threshold {RECALL_THRESHOLD:.4f}"
            if passed
            else f"Correctness test FAILED: recall {bench['recall']:.4f} < threshold {RECALL_THRESHOLD:.4f}"
        )
        return {
            "type": "RunCorrectnessTest",
            "passed": passed,
            "total_queries": int(bench.get("total_queries", 0) or 0),
            "recall": float(bench.get("recall", 0.0) or 0.0),
            "recall_threshold": RECALL_THRESHOLD,
            "failed_queries": [],
            "message": message,
            "system_observation": {
                "before": observation_before,
                "after": observation_after,
                "server_pid": child.pid,
                "benchmark_pid": benchmark_proc.pid,
            },
        }
    except Exception as exc:  # noqa: BLE001
        return _error_result(
            str(exc),
            system_observation=(
                {
                    "before": observation_before,
                    "after": _collect_system_observation(cpu_cores=cpu_cores, focus_pids=(child.pid,))
                    if child is not None
                    else None,
                    "server_pid": child.pid if child is not None else None,
                    "benchmark_pid": benchmark_proc.pid if benchmark_proc is not None else None,
                }
                if observation_before is not None or child is not None or benchmark_proc is not None
                else None

use serde::{Deserialize, Serialize};
use std::sync::Arc;
use std::time::Instant;
use tokio::sync::Semaphore;

use rand::seq::SliceRandom;
use rand::SeedableRng;

use crate::loader::IndexedVector;

/// Request body for the `/search` endpoint.
#[derive(Debug, Clone, Serialize)]
pub struct SearchRequest {
    pub vector: Vec<f32>,
    pub top_k: u32,
}

/// A single search result returned by the server.
#[derive(Debug, Clone, Deserialize)]
pub struct SearchResult {
    pub id: u64,
    pub distance: f64,
}

/// Response from the `/search` endpoint.
#[derive(Debug, Clone, Deserialize)]
pub struct SearchResponse {
    pub results: Vec<SearchResult>,
}

/// Result of a single query, including latency and returned results.
#[derive(Debug, Clone)]
pub struct QueryResult {
    pub query_index: usize,
    pub results: Vec<SearchResult>,
    pub latency_ms: f64,
}

/// Send warmup queries to the server. Results are discarded.
pub async fn run_warmup(
    client: &reqwest::Client,
    server_url: &str,
    queries: &[IndexedVector],
    warmup_count: usize,
) {
    let url = format!("{}/search", server_url.trim_end_matches('/'));
    let count = warmup_count.min(queries.len());

    for q in queries.iter().take(count) {
        let req = SearchRequest {
            vector: q.vector.clone(),
            top_k: 10,
        };
        // Fire and forget – ignore errors during warmup.
        let _ = client.post(&url).json(&req).send().await;
    }
}

/// Run all queries concurrently with a semaphore-based concurrency limit.
///
/// The query order is shuffled deterministically using the provided `seed`.
/// Each query is sent as a POST `/search` request with `top_k=10`.
/// Returns a `QueryResult` for every query, preserving the original query index.
pub async fn run_queries(
    client: &reqwest::Client,
    server_url: &str,
    queries: &[IndexedVector],
    concurrency: usize,
    seed: u64,
) -> Vec<QueryResult> {
    let url = format!("{}/search", server_url.trim_end_matches('/'));

    // Build (original_index, query) pairs and shuffle deterministically.
    let mut indexed: Vec<(usize, &IndexedVector)> = queries.iter().enumerate().collect();
    let mut rng = rand::rngs::StdRng::seed_from_u64(seed);
    indexed.shuffle(&mut rng);

    let semaphore = Arc::new(Semaphore::new(concurrency));
    let client = client.clone();
    let url = Arc::new(url);

    let mut handles = Vec::with_capacity(indexed.len());

    for (idx, query) in indexed {
        let permit = semaphore.clone().acquire_owned().await.unwrap();
        let client = client.clone();
        let url = Arc::clone(&url);
        let vector = query.vector.clone();

        let handle = tokio::spawn(async move {
            let req = SearchRequest {
                vector,
                top_k: 10,
            };

            let start = Instant::now();
            let resp = client.post(url.as_str()).json(&req).send().await;
            let latency_ms = start.elapsed().as_secs_f64() * 1000.0;

            drop(permit);

            let results = match resp {
                Ok(r) => r
                    .json::<SearchResponse>()
                    .await
                    .map(|sr| sr.results)
                    .unwrap_or_default(),
                Err(_) => Vec::new(),
            };

            QueryResult {
                query_index: idx,
                results,
                latency_ms,
            }
        });

        handles.push(handle);
    }

    let mut results = Vec::with_capacity(handles.len());
    for handle in handles {
        if let Ok(qr) = handle.await {
            results.push(qr);
        }
    }

    results
}

