    fn test_search_result_deserialize() {
        let json = r#"{"id": 42, "distance": 1.5}"#;
        let r: SearchResult = serde_json::from_str(json).unwrap();
        assert_eq!(r.id, 42);
        assert!((r.distance - 1.5).abs() < f64::EPSILON);
    }

    #[test]
    fn test_search_response_deserialize() {
        let json = r#"{"results": [{"id": 1, "distance": 0.5}, {"id": 2, "distance": 1.0}]}"#;
        let resp: SearchResponse = serde_json::from_str(json).unwrap();
        assert_eq!(resp.results.len(), 2);
        assert_eq!(resp.results[0].id, 1);
    }

    #[test]
    fn test_deterministic_shuffle() {
        let queries: Vec<IndexedVector> = (0..20)
            .map(|i| IndexedVector {
                id: i,
                vector: vec![i as f32],
            })
            .collect();

        let shuffle = |seed: u64| -> Vec<usize> {
            let mut indexed: Vec<(usize, &IndexedVector)> =
                queries.iter().enumerate().collect();
            let mut rng = rand::rngs::StdRng::seed_from_u64(seed);
            indexed.shuffle(&mut rng);
            indexed.iter().map(|(i, _)| *i).collect()
        };

        // Same seed → same order
        assert_eq!(shuffle(42), shuffle(42));
        // Different seed → different order (extremely unlikely to collide)
        assert_ne!(shuffle(42), shuffle(99));
    }
}

use serde::{Deserialize, Serialize};
use std::path::Path;

/// A vector with its ID, as stored in the JSON data files.
#[derive(Debug, Clone, Deserialize)]
pub struct IndexedVector {
    pub id: u64,
    pub vector: Vec<f32>,
}

/// A single item in a bulk insert request.
#[derive(Debug, Clone, Serialize)]
pub struct InsertItem {
    pub id: u64,
    pub vector: Vec<f32>,
}

/// Request body for the `/bulk_insert` endpoint.
#[derive(Debug, Serialize)]
pub struct BulkInsertRequest {
    pub vectors: Vec<InsertItem>,
}

/// Response from the `/bulk_insert` endpoint.
#[derive(Debug, Deserialize)]
pub struct BulkInsertResponse {
    pub status: String,
    pub inserted: usize,
}

/// Load base vectors from a JSON file.
///
/// The file should contain a JSON array of `{"id": u64, "vector": [f32; 128]}` objects.
pub async fn load_vectors_from_file(path: &str) -> Result<Vec<IndexedVector>, Box<dyn std::error::Error>> {
    let path = Path::new(path);
    let content = tokio::fs::read_to_string(path).await?;
    let vectors: Vec<IndexedVector> = serde_json::from_str(&content)?;
    Ok(vectors)
}

/// Bulk insert vectors into the server via HTTP POST `/bulk_insert`.
///
/// Vectors are split into batches of `batch_size` to avoid oversized request bodies.
/// Returns the total number of successfully inserted vectors.
pub async fn bulk_insert_vectors(
    client: &reqwest::Client,
    server_url: &str,
    vectors: &[IndexedVector],
    batch_size: usize,
) -> Result<usize, Box<dyn std::error::Error>> {
    let url = format!("{}/bulk_insert", server_url.trim_end_matches('/'));
    let mut total_inserted: usize = 0;

    for chunk in vectors.chunks(batch_size) {
        let items: Vec<InsertItem> = chunk
            .iter()
            .map(|v| InsertItem {
                id: v.id,
                vector: v.vector.clone(),
            })
            .collect();

        let request = BulkInsertRequest { vectors: items };

        let resp = client
            .post(&url)
            .json(&request)
            .send()
            .await?
            .error_for_status()?
            .json::<BulkInsertResponse>()
            .await?;

        total_inserted += resp.inserted;
    }

    Ok(total_inserted)
}

