use crate::api::*;
use crate::distance::{self, nearest_centroid, DIM};
use parking_lot::{Mutex, RwLock};
use rayon::prelude::*;
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};

const PRIMARY_CLUSTERS: usize = 256;
const SECONDARY_CLUSTERS: usize = 64;
const PRIMARY_PROBE: usize = 12;
const FINAL_CLUSTER_PROBE: usize = 128;
const TRAINING_SAMPLES: usize = 196_608;
const PRIMARY_KMEANS_ITERS: usize = 6;
const SECONDARY_KMEANS_ITERS: usize = 5;
const MAX_RESULTS: usize = 10;

pub struct VectorDB {
    raw: RwLock<RawStore>,
    index: RwLock<Option<Arc<HierarchicalIndex>>>,
    build_lock: Mutex<()>,
    dirty: AtomicBool,
}

struct RawStore {
    ids: Vec<u64>,
    vectors: Vec<f32>,
}

struct HierarchicalIndex {
    primary_centroids: Vec<f32>,
    secondary_centroids: Vec<f32>,
    cluster_offsets: Vec<usize>,
    cluster_ids: Vec<u64>,
    cluster_vectors: Vec<f32>,
}

struct TopK {
    ids: [u64; MAX_RESULTS],
    distances: [f32; MAX_RESULTS],
    len: usize,
    limit: usize,
}

impl VectorDB {
    pub fn new() -> Self {
        rayon::ThreadPoolBuilder::new().num_threads(4).build_global().ok();

        Self {
            raw: RwLock::new(RawStore {
                ids: Vec::with_capacity(1_100_000),
                vectors: Vec::with_capacity(1_100_000 * DIM),
            }),
            index: RwLock::new(None),
            build_lock: Mutex::new(()),
            dirty: AtomicBool::new(true),
        }
    }

    pub fn insert(&self, id: u64, vector: Vec<f32>) {
        if vector.len() != DIM {
            return;
        }

        let mut raw = self.raw.write();
        raw.ids.push(id);
        raw.vectors.extend_from_slice(&vector);
        self.dirty.store(true, Ordering::Release);
    }

    pub fn bulk_insert(&self, vectors: Vec<(u64, Vec<f32>)>) -> usize {
        let mut inserted = 0usize;
        let mut raw = self.raw.write();

        raw.ids.reserve(vectors.len());
        raw.vectors.reserve(vectors.len() * DIM);

        for (id, vector) in vectors {
            if vector.len() != DIM {
                continue;
            }
            raw.ids.push(id);
            raw.vectors.extend_from_slice(&vector);
            inserted += 1;
        }

        if inserted > 0 {
            self.dirty.store(true, Ordering::Release);
        }

        inserted
    }

    pub fn search(&self, vector: &[f32], top_k: u32) -> Vec<SearchResult> {
        if vector.len() != DIM || top_k == 0 {
            return Vec::new();
        }

        let index = self.ensure_index();
        let top_k = usize::min(top_k as usize, MAX_RESULTS);

        let mut primary_distances = [0.0f32; PRIMARY_CLUSTERS];
        distance::l2_distance_batch(
            vector,
            &index.primary_centroids,
            PRIMARY_CLUSTERS,
            &mut primary_distances,
        );

        let mut best_primary_ids = [0usize; PRIMARY_PROBE];
        let mut best_primary_distances = [f32::MAX; PRIMARY_PROBE];
        let mut best_primary_len = 0usize;
        for (cluster_id, &dist) in primary_distances.iter().enumerate() {
            push_smallest(
                &mut best_primary_ids,
                &mut best_primary_distances,
                &mut best_primary_len,
                cluster_id,
                dist,
            );
